struct mat_fac {};
struct color { float r, g, b, a; };

extern "C" void *operator_new(unsigned, unsigned, const char *, int)
  __asm__("__nw__FUiUiPCci");
extern "C" mat_fac *copy_mat_fac(mat_fac *, const mat_fac &)
  __asm__("__7mat_facRC7mat_fac");
extern "C" void copy_entity(void *, const void *)
  __asm__("copy_instance_data__6entityRC6entity");
extern const char source_name[];

__asm__(".equ __nw__FUiUiPCci,0x002AC578");
__asm__(".equ __7mat_facRC7mat_fac,0x002BC948");
__asm__(".equ copy_instance_data__6entityRC6entity,0x0012EB50");
__asm__(".equ source_name,0x004EF8B0");

class Random {
public:
  unsigned int NextRand();
  float randf(float end) {
    unsigned int r = NextRand();
    return r * (1.0f / 32767) * end;
  }
};

__asm__(".equ NextRand__6Random,0x00112C68");
extern Random *g_random_ptr;
__asm__(".equ g_random_ptr,0x00432360");

inline float random(float end) {
  float r = g_random_ptr->randf(end);
  return r;
}

class lensflare {
  char entity_data[516];
  float brightness;
  float speed;
  float farrange;
  float amount;
  float target;

  struct flare {
    float offset;
    float size;
    mat_fac *texture;
    color col;
  };

  int nflares;
  flare flares[8];
  float los_time;
  float los_freq;

public:
  void copy_instance_data(const lensflare &b);
};

void lensflare::copy_instance_data(const lensflare &b)
{
  speed = b.speed;
  amount = b.amount;
  target = b.target;
  farrange = b.farrange;

  nflares = b.nflares;
  for (int i = 0; i < nflares; i++)
  {
    mat_fac *memory = (mat_fac *)operator_new(272, 0, source_name, 0);
    flares[i].texture = copy_mat_fac(memory, *b.flares[i].texture);
    flares[i].offset = b.flares[i].offset;
    flares[i].size = b.flares[i].size;
    flares[i].col = b.flares[i].col;
  }

  los_freq = b.los_freq;
  los_time = random(los_freq);

  copy_entity(this, &b);
}
